data.variablesTransform:
{
  "msg": [{
    "create":{
      "integrationId": $state.context.REQUEST.DATA.integration.id,
      "modelId": $state.context.REQUEST.DATA.model.id,
      "message": $state.context.REQUEST.DATA.model.name
        & " synchronization failed. An unexpected error occured. See logs for details",
      "typeId": "Failure",
      "data": $state
    }
  },{
  "create": {
    "integrationId": $state.context.REQUEST.DATA.integration.id,
    "message": $state.context.REQUEST.DATA.model.name
        & " synchronization failed. An unexpected error occured. See logs for details",
    "typeId": "Failure",
    "global":true
  }
}]
}

{
  "msg": {
    "create": {
      "integrationId": $state.context.REQUEST.DATA.integration.id,
      "modelId": $state.context.REQUEST.DATA.model.id,
      "message": $state.context.REQUEST.DATA.model.name 
        & " with ID: "
        & $state.context.REQUEST.DATA.id
        & " failed to return results from SuiteQL query",
      "typeId": "Failure"
    }
  }
}

data.query:
query Query($where: SupplierWhereInput, $orderBy: [SupplierOrderByInput!], $first: Int, $after: String) {
  supplier(where: $where, orderBy: $orderBy, first: $first, after: $after) {
  total  
  edges {
      node {
        id
        code
        active
        dunsNumber
        externalId
        name
        scac
        customData
        integrationData
        supplierStatusId
        supplierTypeId
      }
    }
  }
}

query Query($where: SupplierAddressWhereInput, $orderBy: [SupplierAddressOrderByInput!], $first: Int, $after: String) {
  supplierAddress(where: $where, orderBy: $orderBy, first: $first, after: $after) {
  total
    edges {
      node {
        id
        code
        externalId
        supplierId
      }
    }
  }
}

data.transform:
(
$updates:=$innerJoin( $.supplierAddress.edges.node, $state.context.REMOTE.supplierAddress, 'externalId', 'nkey', 'joinedKey', { 'grouped': true } );
$inactivate:= $leftAntiJoin( $.supplierAddress.edges.node, $state.context.REMOTE.supplierAddress, 'externalId', 'nkey');
$new:= $leftAntiJoin( $state.context.REMOTE.supplierAddress, $.supplierAddress.edges.node, 'nkey', 'externalId');

$sortedData:={
"updateAddress": $updates,
"inactivateAddress": $inactivate ,
"createAddress": $new
};
{
  "createPayload":[ $new.{"create":{
    "code": addressee & " (" & $string(nkey) & ")",
    "addressee":addressee,
    "supplierId": $state.context.LOCAL.supplier.id,
    "externalId":nkey.$string(),
    "address": {
      "lines": [addr1 & "",addr2, addr3],
      "city": city & "",
      "state": state & "",
      "postalCode": zip & "",
      "country": country & ""
    },
    "defaultBilling": defaultbilling='T',
    "defaultShipping": defaultshipping='T',
    "integrationData":$}}],
  "updatePayload": [$updates.{"update": joinedKey.{
    "code": addressee & " (" & $string(nkey) & ")",
    "addressee":addressee,
    "supplierId": $state.context.LOCAL.supplier.id,
    "externalId":nkey.$string(),
    "address": {
      "lines": [addr1 & "",addr2, addr3],
      "city": city & "",
      "state": state & "",
      "postalCode": zip & "",
      "country": country & ""
    },
    "defaultBilling": defaultbilling='T',
    "defaultShipping": defaultshipping='T',
    "integrationData":$
  },"where": {"id": id}}],
  "inactivatePayload": [$inactivate.{"update": {"active": false},"where": {"id": id}}]
}
)

